local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.templates
rows[#rows+1]={"Their numbers are too many to count. Their defenses look impenetrable.$b$bI saw no weaknesses to exploit, $r.","숫자가 너무 많아서 수를 셀 수 없어서 방어력이 어긋나지 않습니다$b$b저는 이점을 이용할 수 있는 약점이 없었습니다. $r."}
rows[#rows+1]={"Then listen well, $c.$B$BCan you feel the power radiating from me? Does your morale not swell? Aye, it is the same for the other side. To disrupt their defenses and thin out their troops will be no easy task, but it must be done! Victory will be ours!","그럼 잘 들어봐 $c.$B$B내 힘 을 느낄 수 있습니까? 당신의 도덕 이 팽창 하지 않습니까? 네, 반대편 에 대해서도 마찬가지 입니다. 그들의 방어 를 방해 하고 군대를 희미 시키기는 쉬운 일이 아닙니다. 하지만 반드시 이루어져야 합니다. 승리는 우리 에게 있을 것입니다."}
rows[#rows+1]={"Then listen well, $r.$B$BSeveral months ago, the Magistrate of Lakeshire sent envoys to Ironforge, pleading with the King for assistance with the Blackrock incursions coming from Redridge and the Burning Steppes.$B$BPrincess Moira volunteered to help, against my pleadings. I was assigned twenty elite guardsmen to protect the Princess through the perilous journey from the Loch to Lakeshire.","그럼 잘 들어봐 $r.$B$B몇 달 전, 레이크샤이어의 판사는 아이언포지에 사명을 보내, 레드리지와 불타는 스텝에서 오는 블랙록 침략에 도움을 요청했습니다.$B$B모이라 공주가 내 요구에 반해 자원봉사자로 도움을 주었고, 저는 록에서 레이크샤이어까지 위험한 여정을 통해 공주를 보호하기 위해 20명의 엘리트 경호가 임명되었습니다."}
rows[#rows+1]={"Then we have a deal. I'll see you in battle, $n.","그럼 협상해 전투에서 보자 $n."}
rows[#rows+1]={"There $g he : she; is!","저기 $g 그는: 그녀는; 그것은!"}
rows[#rows+1]={"There are Tian disciples in town celebrating the Brewmoon, $n! Surely they could use their training to help us. Talk to them and see if they can stop these yaungol!","시내에는 천교들이  ⁇ 월을 축하하고 있습니다. $n그 훈련은 우리를 도울 수 있을 거고, 이 야구들을 막을 수 있는지 알아봐"}
rows[#rows+1]={"There are Tian mistweavers here from the Tian monastery, $n. Their skills with mistweaving would allow us to fight even longer! Ask them to aid us in this fight.","천안 수도원에서 온 천안의 빗물 파는 사람들이 있습니다. $n그들의 실력으로 우리는 더 오래 싸울 수 있습니다."}
rows[#rows+1]={"There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Alliance takes time to give something back to these innocents.  This time is called Children's Week.\010","전쟁은 비용이 든다 $c그 비용 은 부모 를 잃은 어린이 들 이 아제로스다른 사람을 찾아갈 수 없는 아이들은 종종 스스로 돌볼 수 있을 정도로 나이가 들 때까지 살기 위해 이곳에 왔습니다.$B$B봄에 한 주씩 얼라이언스는 이 무고한 사람들에게 무언가를 돌려주는 시간을 필요로 합니다. 이 시간을 어린이 주라고 합니다.\010"}
rows[#rows+1]={"There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Horde takes time to give something back to these innocents.  This time is called Children's Week.\010","전쟁은 비용이 든다 $c그 비용 은 부모 를 잃은 어린이 들 이 아제로스다른 사람을 찾아갈 수 없는 아이들은 종종 스스로 돌볼 수 있을 정도로 나이가 들 때까지 살기 위해 이곳에 왔습니다.$B$B봄에 한 주씩 호드는 이 무고한 사람들에게 무언가를 돌려주는 시간을 필요로 합니다. 이 시간을 어린이 주라고 합니다.\010"}
rows[#rows+1]={"There are demons to kill, $c.  Do you have the backbone to do what needs to be done?","죽이는 악마들이 있어 $c해야 할 일을 할 수 있는 척추가 있습니까?"}
rows[#rows+1]={"There are few left in the world who can prepare the Ward of Waking, $N. We are fortunate that I am among them.","각성의 수호물을 만들 수 있는 자는 세상에 얼마 남지 않았다, $N. 내가 그중 하나라 다행이지."}
rows[#rows+1]={"There are few left in the world who can prepare the Ward of Waking, $n. We are fortunate that I am among them.","$n, 각성의 물약을 조제할 수 있는 이는 이 세계에 몇 안 남았습니다. 제가 그중 하나라는 사실을 감사하게 생각하셔야 할 겁니다."}
rows[#rows+1]={"There are plenty of thermal vents up ahead, $n. Feel free to use them if you get into a jam.","앞으로 열풍기가 많이 있습니다. $n- 안 돼, 문제가 생기면 쓸 수 있어"}
rows[#rows+1]={"There are some Vale marksmen in town that stopped to rest for the night, $n. They have defended the Gate of the Setting Sun against the mantid for many years with their mortars. See if you can wake them up!","마을에 몇 명의 발격수들이 있어 $n그들은 수년간 포탄으로 서양의 문을 방어해 왔고"}
rows[#rows+1]={"There are some damaged cannons inside the storehouses and behind the inn, $n. If you could repair them, the villagers could use them to blast the yaungol!","창고 안과 숙소 뒤에 몇 개의 상기가 손상되어 있습니다. $n만약 당신이 그들을 고칠 수 있다면 마을 사람들은 야롱을 폭발시킬 수도 있습니다!"}
rows[#rows+1]={"There are those who seek to lie and twist the truth.  Seers, on the other hand, bring the truth to light.$B$BThe purpose of this library, $n, is to make a seer out of everyone.","거짓을 하고 진리를 왜곡하는 자들이 있나니 시야가 진리를 드러내는 자들이 있나니$B$B이 도서관의 목적은 $n, 모든 사람을 시야가 되게 하는 것입니다."}
rows[#rows+1]={"There aren't any more challengers who want to fight you, $n. You're just too damned good.\010You still want a fight? Go pick up a challenge card and talk to me again.","더 이상 당신과 싸우고 싶은 도전자가 없습니다 $n넌 너무 잘했어\010아직 싸우고 싶니 도전 카드 좀 가져와 다시 얘기해"}
rows[#rows+1]={"There aren't many of us left, $n.  The return of our old enemy is a cause for great concern.","우리들 중은 많지 않아요 $n우리의 옛 적의 귀환은 큰 우려의 대상이 됩니다."}
rows[#rows+1]={"There can be only one outcome to such a battle: death for one side or the other. Let $n prove $g himself : herself; upon the bones of those outsiders who have fallen before!","발할라스에서의 전투는 어느 한 쪽이 죽어야만 끝이 난다. 살아남는 자가 될지, 죽는 자가 될지, $n|1은;는; 발할라스에서 전사한 이방인들의 뼈 위에서 자신을 시험하게 될 것이다."}
rows[#rows+1]={"There comes a time when the life we know falls short.  We are trapped and look for answers, and we find hope burning in dark places.$B$BOnly then, $n, do we take our first steps to freedom.","우리가 알고 있는 삶이 짧아지는 때가 온다. 우리는 함정에 갇혀서 답을 찾고 있습니다. 그리고 어두운 곳에서 희망이 불타는 것을 발견합니다.$B$B그때만, $n, 우리는 자유를 향한 첫걸음을 내딛을 수 있습니다."}
rows[#rows+1]={"There goes the finest $c I have the honor of knowing.","가장 좋은 건 $c 내가 아는 영광이 있어"}
rows[#rows+1]={"There is a great deal at stake within the blue dragonflight, $c.$b$bSoon, a new aspect must be chosen to take the place of Malygos.$b$bArygos aspires to follow in the footsteps of his father, renewing the misguided aggression against all who wield magic. This path, I feel, would lead to the end of our kind.$b$bThe remnants of our flight are divided on this fateful issue, and I fear that Arygos will stop at nothing to meet his ends...","파란색 드래곤 비행에서 많은 것이 위기에 놓여 있습니다. $c.$b$b곧 마일고스의 자리를 대신하는 새로운 측면이 선택되어야 합니다.$b$b아리고스는 아버지의 발자취를 따라가며 마술을 하는 모든 사람들에게 대한 잘못된 공격에 대해 다시 한 번 도전합니다. 이 길은 우리 종의 종말로 이어질 것이라고 생각합니다.$b$b우리의 비행의 잔류는 이 운명적인 문제에 대해 나뉘어 있고, 아리고스가 그의 목적을 달성하기 위해 아무 것도 멈추지 않을 것이라고 두려워합니다."}
rows[#rows+1]={"There is little else I can teach you, $c. Please, speak with my colleague Kalinda if you wish to know more of the craft.","내가 당신에게 가르쳐 줄 수 있는 것은 거의 없습니다. $c 공예에 대해 더 알고 싶다면 제 동료 칼린다와 이야기해 주세요."}
rows[#rows+1]={"There is much that you do not understand, $R. The Master sees all.","너 같은 작자가 이해할 수 없는 일은 많다, $r. 주인님은 모든 걸 아신다."}
rows[#rows+1]={"There is much that you do not understand, $r. The Master sees all.","너 같은 작자가 이해할 수 없는 일은 많다, $r. 주인님은 모든 걸 아신다."}
rows[#rows+1]={"There is much work left to be done, $n! Continue to strike down our enemies!","아직 해야 할 일이 많아요 $n계속 적들을 공격해!"}
rows[#rows+1]={"There is no end to these trolls, $c.","이 트롤들은 끝없는 존재입니다. $c."}
rows[#rows+1]={"There is no stopping $n! Sarinexx has been massacred!","멈출 수 없습니다 $n사리네엑스가 학살당했어"}
rows[#rows+1]={"There is nothing left to be done for the Vale at this time, $n. The mogu disappeared shortly after you killed their leader. We are safe, thanks to you.","이 시간에는 밸리에게 할 일이 없어 $n모가들은 당신이 그들의 지도자를 죽인 직후 사라졌어요"}
rows[#rows+1]={"There is nothing more that I can do for you, $n. Take what I have taught you, and use it elsewhere.","더할 수 있는 게 없어요 $n내가 가르쳐준 것을 가져서 다른 곳에 써라"}
rows[#rows+1]={"There is one that I know of here in Thunder Bluff that can aid you in your journey to Alterac Valley. On the Hunter Rise look for Taim Ragetotem. May you find what you are looking for $n.","여기 내가 아는 한 사람이 있습니다 썬더 블러프 알테락밸리로 가는 길에 도움이 될 수 있습니다. 사냥꾼 상승에서 타임 라게토메트를 찾아보세요. $n."}
rows[#rows+1]={"There may still be a solution. Come here, $n. I will explain what I need.","흠, 그녀를 치료할 방법이 아직 있을 것이오. 이쪽으로 오시오, $n. 필요한 걸 알려주겠소."}
rows[#rows+1]={"There we are, $n.  The Scroll is fixed!  Hooray!","자, 다 됐어, $n. 두루마리를 다시 붙였다고! 만세!"}
rows[#rows+1]={"There we are, $n.  The toxin is ready.","다 됐소, $n. 독약이 준비됐군."}
rows[#rows+1]={"There we go, $n! This fat'll do the trick fer sure! And now for some real swabbin'!","이제 됐네요, $n! 이 덩어리라면 될 거예요! 이제 걸레질 좀 제대로 하겠네!"}
rows[#rows+1]={"There will be no second chances, $r.","두 번째 기회가 없을 겁니다. $r."}
rows[#rows+1]={"There will be time enough to speak of preparations for battle against Twilight's Hammer. Today, we celebrate $n's victory!","Twilight's Hammer에 대한 준비에 대해 이야기 할 충분한 시간이 있을 것입니다. 오늘 우리는 $n의 승리를 축하합니다!"}
rows[#rows+1]={"There you are, $n! I thought you'd forgotten about me.","여기 있네 $n날 잊었다고 생각했어"}
rows[#rows+1]={"There you go, $n. Good thing my powers of divination and summoning still work in this ghostly state, huh?","여기 있네 $n다행이 내 사상과 소환 능력은 여전히 이 유령 상태에서 작동하잖아요?"}
rows[#rows+1]={"There you go, $r.","여기 있네, $r."}
rows[#rows+1]={"There you have it, $n. A mighty bow for a mighty hunter. Use it well in service of the Alliance.","여기 있네 $n강력한 사냥꾼을 위한 강력한 활이 얼라이언스."}
rows[#rows+1]={"There you have it, $n. All the safe approaches to the Twilight Highlands. Unleash havoc on our foes!","여기 있네 $nTwilight Highlands에 안전한 접근을 해소해"}
rows[#rows+1]={"There'll be a new trade risin' up round your carcass, $n. We'll call it 'flesh-craftin.'","네 사체를 둘러싼 새로운 거래가 일어날 거야 $n- '육신'이라고 부를게요"}
rows[#rows+1]={"There's Farstrider Enclave now, $c. Not far to go... look out!  Troll ambush!!","이제 곧 원정순찰대 초소입니다. 얼마 안 남았습니다... 조심하세요! 트롤의 기습입니다!"}
rows[#rows+1]={"There's a lot of money out there in that jungle, $r.  Can you see it?$b$bNo, it doesn't look like gold or copper.  It looks like raptor hides, and mineral veins, and ancient troll artifacts.$b$bOK, maybe the mineral veins might look like gold or copper.$b$bBut still, you get my point, right?","그 정글에는 돈이 많고 $r- 보셨나요?$b$b금이나 구리처럼 보이지 않고 암컷의 피부와 미네랄 혈관과 고대 트롤 유물처럼 보입니다$b$b자, 아마도 미네랄 혈관은 금이나 구리처럼 보일지도 모릅니다.$b$b하지만 여전히, 내 말 이해가 되죠?"}
rows[#rows+1]={"There's a whole vast forest out there, $c. Let the shaman play with the spirits and the warriors toy with their swords. Terokkar is where I'll make my fortune.","저 밖에는 거대한 숲이 있습니다. $c 샤만들이 영들과, 그리고 전사들은 검으로 놀게 해줘요. 테로카르는 내가 부를 쌓을 곳이에요."}
rows[#rows+1]={"There's another one! Kill the $r!","또 하나 있어 $r를 죽여라"}
rows[#rows+1]={"There's more to this than we know, $n.  I can guarantee you that much.","우리가 아는 것보다 더 많은 것이 있습니다. $n- 그 대상을 보장할 수 있어요"}
rows[#rows+1]={"There's my best friend! Come on, $n, dance with us!","내 친구! $n우리랑 춤을 추세요!"}
rows[#rows+1]={"There's no time to waste, $n. My intel tells me that the yaungol are about to launch an all-out last ditch assault. We're all counting on you to kill Chief Ragemesa.","시간 낭비가 없어, $n 내 정보에 따르면 야롱들은 마지막 격포 공격을 시작할 예정이라고"}
rows[#rows+1]={"There's no turning back now, $n. Stay close and watch my back.","$n, 임무를 맡았으니 이제 앞으로 나아갈 길만이 있을 뿐이오. 바짝 따라오면서 내 뒤를 부탁하오."}
rows[#rows+1]={"There, $n, I think I've figured it out!","여기, $n, 나는 그것을 알아냈다고 생각합니다!"}
rows[#rows+1]={"There, $n, now you will be able to speak with, and understand, the Winterfin murlocs.","됐습니다, $n. 이제 당신은 겨울지느러미 멀록과 대화도 할 수 있고, 말뜻도 이해할 수 있습니다."}
rows[#rows+1]={"There, $n.  You may now speak to the Bloodscalp chief and his witchdoctor.","자, $n. 이제 붉은머리 부족 족장과 그의 의술사에게 가서 얘기해 보시오."}
rows[#rows+1]={"There, $n. It is done.","여기, $n."}
rows[#rows+1]={"There, there, $n, worry not! Which piece of the amulet have you misplaced?$B$BDid you check all of your bags and the bank?","저기, 저기 $n걱정 마, 어떤 줄거리의 조각이 잘못됐어?$B$B가방과 은행을 확인했나요?"}
rows[#rows+1]={"There.  I am finished with your robe, $n.","됐어요, $n. 로브가 완성되었습니다."}
rows[#rows+1]={"There... There's no more time for me. I'm done for. Finish me off, $n. Do it or they'll kill us both. $n... Remember Argus. Don't let that happen to this world.","내겐 시간이 없어, 그만해 $n- 그렇게 해면 둘 다 죽게 될 거야 $n아거스 기억해, 이 세상에 이런 일이 일어나지 않도록 해"}
rows[#rows+1]={"There... There's no more time for me. I'm done for. Finish me off, $n. Do it or they'll kill us both. $n... Remember Elwynn. This world is worth saving.","내겐 시간이 없어, 그만해 $n- 그렇게 해면 둘 다 죽게 될 거야 $n엘윈을 기억해줘 이 세상은 구원받을 가치가 있어"}
rows[#rows+1]={"There... There's no more time for me. I'm done for. Finish me off, $n. Do it or they'll kill us both. $n... Remember Gilneas, our beloved home. This world is worth saving.","내겐 시간이 없어, 그만해 $n- 그렇게 해면 둘 다 죽게 될 거야 $n...우리 사랑하는 고향인 길네아스를 기억하세요. 이 세상은 구원받을 가치가 있습니다."}
rows[#rows+1]={"There... There's no more time for me. I'm done for. Finish me off, $n. Do it or they'll kill us both. $n... Remember Gnomeregan! This world is worth saving.","내겐 시간이 없어, 그만해 $n- 그렇게 해면 둘 다 죽게 될 거야 $n...그노메리건을 기억해줘 이 세상은 구원받을 가치가 있어"}
rows[#rows+1]={"There... There's no more time for me. I'm done for. Finish me off, $n. Do it or they'll kill us both. $n... Remember Kezan, our beloved home. This world is worth saving.","내겐 시간이 없어, 그만해 $n- 그렇게 해면 둘 다 죽게 될 거야 $n케잔을 기억해줘, 우리 사랑하는 고향이 이 세상은 구원받을 가치가 있어"}
